        :Stay in State 186;
        if (Fast charging disabled?) then (Yes)
          :Switch to State 12;
          stop
        else (No)
        endif
      elseif (Remote mode disabled?) then (Yes)
        :Shut down;
        stop
      else (No)
      endif
    }

    partition "Fourth Condition" {
      if (Pet mode request received && Front MCU initialization == 0?) then (Yes)
        :Remain in State 186;
        if (Fast charging inactive?) then (Yes)
          :Switch to State 12;
          stop
        else (No)
        endif
      else (No)
      endif
      if (Pet mode ends?) then (Yes)
        :Shut down;
        stop
      else (No)
      endif
    }

    partition "Fifth Condition" {
      if (Battery SOC == 20 && Front MCU initialization == 0?) then (Yes)
        :Stay in State 186;
        if (Fast charging disabled?) then (Yes)
          :Switch to State 12;
          stop
        else (No)
        endif
      else (No)
      endif
      if (SOC reaches 80 && DCDC state == 3?) then (Yes)
        :Shut down;
        stop
      else (No)
      endif
    }

  else (No)
    :Continue;
    stop
  endif
else (No)
  :Continue;
  stop
endif
